#!/bin/sh
set -eu
app=$(docker ps --filter name=cardapiodigitalbh_app --format '{{.ID}}' | head -n1)
test -n "$app"
docker exec "$app" php artisan tinker --execute='$source=tempnam(sys_get_temp_dir(), "cdbh-source-"); $image=imagecreatetruecolor(2000, 1000); imagefill($image, 0, 0, imagecolorallocate($image, 20, 140, 90)); imagepng($image, $source); imagedestroy($image); $upload=new Illuminate\Http\UploadedFile($source, "teste.png", "image/png", null, true); $output=app(App\Services\ImageOptimizer::class)->toWebp($upload); $info=getimagesize($output); throw_unless($info[0] === 1400 && $info[1] === 700 && $info["mime"] === "image/webp", RuntimeException::class, "Falha na otimizacao WebP"); $bytes=filesize($output); $stream=fopen($output, "rb"); Illuminate\Support\Facades\Storage::disk("s3")->put("health/optimized-check.webp", $stream, ["ContentType" => "image/webp"]); fclose($stream); throw_unless(Illuminate\Support\Facades\Storage::disk("s3")->exists("health/optimized-check.webp"), RuntimeException::class, "Falha no MinIO"); Illuminate\Support\Facades\Storage::disk("s3")->delete("health/optimized-check.webp"); @unlink($source); @unlink($output); dump(["dimensions" => "1400x700", "mime" => $info["mime"], "bytes" => $bytes, "storage" => "ok"]);'
if docker service ls | grep -q cdbh_minio_setup; then echo 'Serviço temporário não removido.'; exit 1; fi
